using System;using System.Linq;using System.IO;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using Demo5.FrontEnd;
public static class VerifySettlementRecords {
 static SettlementController C()=>UnityEngine.Object.FindAnyObjectByType<SettlementController>();static void Check(bool x,string m){if(!x)throw new Exception(m);}
 static async Task Tap(Button b){await Task.Delay(100);Canvas.ForceUpdateCanvases();Check(b.IsActive()&&b.IsInteractable(),"Unavailable "+b.name);var r=(RectTransform)b.transform;var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(b.GetComponentInParent<Canvas>().worldCamera,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Blocked "+b.name);ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerClickHandler);await Task.Delay(100);}
 static void Fits(){var o=C().Opening;Canvas.ForceUpdateCanvases();Check(o.RecordBody.preferredHeight<=o.RecordBody.rectTransform.rect.height,"Body overflow "+o.RecordBody.preferredHeight);Check(C().Main.alpha==0,"HUD visible");}
 public static async Task<string> Load(){CampaignSaveStore.TestDirectory=Path.GetFullPath("Temp/NightEventVerification");try{var read=CampaignSaveStore.Read(0,C());Check(read.CanLoad,read.Error);CampaignPersistence.Prepare(read.Data,C());}finally{CampaignSaveStore.TestDirectory=null;}SceneManager.LoadScene("Settlement");await Task.Delay(650);return "Loaded saved completed night branch.";}
 public static async Task<string> Run(){var c=C();var o=c.Opening;string before=JsonUtility.ToJson(CampaignPersistence.Capture(c).Opening);int minute=c.Campaign.MinuteOfDay;await Tap(c.Journal);Check(o.RecordsView.activeSelf&&o.RecordTabs.All(b=>b.gameObject.activeSelf),"Discovered records");for(int i=0;i<4;i++){await Tap(o.RecordTabs[i]);Fits();}Check(o.RecordBody.text.Contains("발자국")&&!o.RecordsContinue.gameObject.activeSelf,"Resolved branch detail");await Tap(o.RecordsReturn);Check(c.ReturnPanel.IsOpen&&!o.RecordsView.activeSelf,"Return report route");await Tap(c.ReturnPanel.Back);Check(c.Main.alpha==1,"HUD not restored");Check(before==JsonUtility.ToJson(CampaignPersistence.Capture(c).Opening)&&minute==c.Campaign.MinuteOfDay,"Read mutated state");var saved=o.State;o.State=new SavedOpeningChapter();await Tap(c.Journal);Check(o.RecordTabs.Count(b=>b.gameObject.activeSelf)==1,"Unseen spoiler");Fits();await Tap(o.RecordsBack);o.State=JsonUtility.FromJson<SavedOpeningChapter>(before);o.State.NightChoice=0;await Tap(c.Journal);Check(o.RecordsContinue.gameObject.activeSelf&&o.RecordBody.text.Contains("아직 결정"),"Pending detail");await Tap(o.RecordsContinue);Check(o.NightView.activeSelf&&!o.RecordsView.activeSelf&&c.Main.alpha==0,"Pending route");await Tap(o.NightBack);o.State=saved;await Tap(c.Journal);Fits();Check(minute==c.Campaign.MinuteOfDay,"Resume without choice cost time");return "PASS all 4 entries, no unseen spoilers, completed branch details, read-only state/time, return-report link, pending-event resume, HUD restoration and body fit.";}
}
